<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CashService;
use EventMenu\Services\OrderFulfillmentService;
use EventMenu\Services\OrderService;
use EventMenu\Services\PaymentService;

Auth::requirePermission('orders.view');$tenantId=em_require_tenant();
function orders_qty(float|int|string$v):string{$q=(float)$v;return abs($q-round($q))<0.0005?(string)(int)round($q):rtrim(rtrim(number_format($q,3,',','.'),'0'),',');}
function orders_channel(string$c):string{return match($c){'counter'=>'Balcão / PDV','pickup'=>'Retirada','delivery'=>'Delivery','table'=>'Mesa / comanda',default=>$c};}
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
    if($action==='status'){
        Auth::requirePermission('orders.manage');$status=(string)($_POST['status']??'');
        try{(new OrderService())->changeStatus($id,$status,'panel');em_flash('ok','Status atualizado.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('orders');
    }
    if($action==='assign-delivery'){
        Auth::requirePermission('delivery.assign');$userId=(int)($_POST['delivery_user_id']??0);
        try{Database::transaction(function(PDO$tx)use($tenantId,$id,$userId):void{$o=$tx->prepare(Database::portableSql($tx,'SELECT id,channel,status FROM orders WHERE id=? AND tenant_id=? FOR UPDATE'));$o->execute([$id,$tenantId]);$order=$o->fetch();if(!$order)throw new RuntimeException('Pedido não encontrado.');if($order['channel']!=='delivery')throw new RuntimeException('Somente pedidos de delivery podem receber entregador.');if(in_array($order['status'],['completed','cancelled'],true))throw new RuntimeException('Pedido já encerrado.');if($userId){$u=$tx->prepare('SELECT id FROM users WHERE id=? AND tenant_id=? AND role="delivery" AND status="active"');$u->execute([$userId,$tenantId]);if(!$u->fetchColumn())throw new RuntimeException('Entregador inválido.');}$tx->prepare('UPDATE orders SET assigned_delivery_user_id=? WHERE id=? AND tenant_id=?')->execute([$userId?:null,$id,$tenantId]);});Auth::audit('order.delivery_assigned','order',(string)$id,['delivery_user_id'=>$userId?:null]);em_flash('ok','Entregador atualizado.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('orders');
    }
    if($action==='manual-pay'){
        Auth::requirePermission('payments.manage');Auth::requirePermission('cash.manage');$s=$pdo->prepare('SELECT total_cents,status,payment_status FROM orders WHERE id=? AND tenant_id=?');$s->execute([$id,$tenantId]);$o=$s->fetch();if(!$o)exit('Pedido não encontrado.');
        if(!in_array($o['payment_status'],['unpaid','failed'],true)){em_flash('error','Este pedido possui pagamento em andamento ou já processado. Não é possível receber em dinheiro agora.');em_go('orders');}
        try{Database::transaction(function()use($id,$tenantId,$o):void{$cash=new CashService();if(!$cash->currentSession())throw new RuntimeException('Abra seu turno de caixa antes de receber dinheiro.');$service=new PaymentService();$payment=$service->create($id,'manual','manual:'.$tenantId.':'.$id.':'.bin2hex(random_bytes(8)));if(($payment['provider']??'manual')!=='manual'&&isset($payment['provider']))throw new RuntimeException('Existe uma cobrança de outro provedor para este pedido.');$service->confirmVerified(['tenant_id'=>$tenantId,'order_id'=>$id,'provider'=>'manual','provider_payment_id'=>'CASH-'.strtoupper(bin2hex(random_bytes(8))),'amount_cents'=>(int)$o['total_cents'],'currency'=>'BRL','account_reference'=>'manual']);$cash->recordPaidPayment((int)$payment['id'],'cash');Auth::audit('payment.cash','order',(string)$id,['cash_session'=>true]);});em_flash('ok','Pagamento em dinheiro confirmado e conciliado no caixa.');}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('orders',['view'=>$id]);
    }
}
$sql='SELECT o.*,c.name customer_name,u.name delivery_name,rt.name table_name,t.label tab_label FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.assigned_delivery_user_id LEFT JOIN restaurant_tables rt ON rt.id=o.table_id LEFT JOIN tabs t ON t.id=o.tab_id WHERE o.tenant_id=?';$args=[$tenantId];if(Auth::role()==='delivery'){$sql.=' AND o.assigned_delivery_user_id=?';$args[]=Auth::id();}$sql.=' ORDER BY o.id DESC LIMIT 150';$s=$pdo->prepare($sql);$s->execute($args);$orders=$s->fetchAll();
$d=$pdo->prepare('SELECT id,name FROM users WHERE tenant_id=? AND role="delivery" AND status="active" ORDER BY name');$d->execute([$tenantId]);$deliveries=$d->fetchAll();
$viewId=(int)($_GET['view']??0);$items=[];$viewOrder=null;$fulfillmentDetails=null;$orderQr=null;
if($viewId){$q=$pdo->prepare('SELECT o.*,c.name customer_name,rt.name table_name FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN restaurant_tables rt ON rt.id=o.table_id WHERE o.id=? AND o.tenant_id=? LIMIT 1');$q->execute([$viewId,$tenantId]);$viewOrder=$q->fetch()?:null;if($viewOrder){$q=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$q->execute([$viewId]);$items=$q->fetchAll();$fulfillment=new OrderFulfillmentService();if($fulfillment->supportsChannel((string)$viewOrder['channel'])&&!empty($viewOrder['public_token'])){try{$fulfillmentDetails=$fulfillment->detailsByToken((string)$viewOrder['public_token']);$orderQr=$fulfillment->qrDataUri((string)$viewOrder['public_token'],280);}catch(Throwable$e){$fulfillmentDetails=null;}}}}
em_header('Pedidos','orders');
?>
<?php if($viewOrder):?><section class="card" style="margin-bottom:18px"><div class="section-head"><div><span class="eyebrow"><?= Security::e(orders_channel((string)$viewOrder['channel'])) ?></span><h2>Pedido #<?= $viewId ?></h2><div class="muted"><?= Security::e($viewOrder['customer_name']??'Consumidor') ?> · <?= Security::e((string)$viewOrder['status']) ?> · <?= Security::e((string)$viewOrder['payment_status']) ?></div></div><a class="button secondary" href="<?= Security::e(app_url('?route=orders')) ?>">Fechar</a></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Qtd.</th><th>Unitário</th><th>Total</th><th>Obs.</th></tr></thead><tbody><?php foreach($items as$i):?><tr><td><?= Security::e($i['name_snapshot']) ?></td><td><?= orders_qty($i['quantity']) ?></td><td><?= em_money($i['unit_price_cents']) ?></td><td><?= em_money($i['total_cents']) ?></td><td><?= Security::e($i['notes']??'') ?></td></tr><?php endforeach;?></tbody></table></div>
<?php if($fulfillmentDetails&&$orderQr):$progress=$fulfillmentDetails['progress'];?><div style="display:grid;grid-template-columns:minmax(210px,280px) minmax(0,1fr);gap:20px;align-items:center;margin-top:20px;padding-top:20px;border-top:1px solid var(--line)"><div style="background:#fff;border-radius:18px;padding:12px"><img src="<?= Security::e($orderQr) ?>" alt="QR do pedido" style="display:block;width:100%;height:auto"></div><div><span class="eyebrow">QR DO PEDIDO</span><h2 style="margin:4px 0 8px">Conferência de retirada</h2><p class="muted">Este QR identifica o pedido. Mesa/comanda não utiliza esta etapa. Em retirada parcial, o QR continua válido até todos os itens serem entregues.</p><div class="metric-grid" style="grid-template-columns:repeat(3,minmax(0,1fr));margin:14px 0"><div class="metric-card"><span>Pedido</span><strong><?= orders_qty($progress['ordered_quantity']) ?></strong></div><div class="metric-card"><span>Entregue</span><strong><?= orders_qty($progress['fulfilled_quantity']) ?></strong></div><div class="metric-card"><span>Falta</span><strong><?= orders_qty($progress['remaining_quantity']) ?></strong></div></div><?php if(Auth::can('orders.fulfill')):?><a class="button primary" href="<?= Security::e(app_url('?route=pickup&token='.rawurlencode((string)$viewOrder['public_token']))) ?>">Abrir retirada deste pedido</a><?php endif;?></div></div><?php elseif((string)$viewOrder['channel']==='table'):?><div class="alert ok" style="margin-top:18px">Pedido de mesa/comanda: não precisa de QR de retirada.</div><?php endif;?></section><?php endif;?>
<section class="card"><div class="section-head"><h2>Operação</h2><span class="muted"><?= count($orders) ?> pedidos recentes</span></div><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Cliente / origem</th><th>Status</th><th>Pagamento</th><th>Total</th><th>Entrega</th><th>Ações</th></tr></thead><tbody><?php foreach($orders as$o):?><tr><td><a href="<?= Security::e(app_url('?route=orders&view='.(int)$o['id'])) ?>">#<?= (int)$o['id'] ?></a><br><span class="muted"><?= Security::e(orders_channel((string)$o['channel'])) ?></span></td><td><?= Security::e($o['customer_name']??'Consumidor') ?><br><span class="muted"><?= Security::e($o['table_name']??$o['delivery_address']??'') ?></span></td><td><span class="badge"><?= Security::e($o['status']) ?></span><?php if(Auth::can('orders.manage')):?><form method="post" class="actions" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach(['pending','confirmed','preparing','ready','out_for_delivery','completed','cancelled']as$st):?><option value="<?= $st ?>"<?= em_selected($o['status'],$st) ?>><?= $st ?></option><?php endforeach;?></select><button class="secondary">Salvar</button></form><?php endif;?></td><td><?= Security::e($o['payment_status']) ?><?php if(Auth::can('payments.manage')&&Auth::can('cash.manage')&&in_array($o['payment_status'],['unpaid','failed'],true)&&!in_array($o['status'],['completed','cancelled'],true)):?><form method="post" style="margin-top:6px" onsubmit="return confirm('Confirmar recebimento deste pedido em dinheiro físico?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="manual-pay"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><button class="secondary">Receber em dinheiro</button></form><?php elseif($o['payment_status']==='pending'):?><br><small class="muted">Cobrança online em processamento</small><?php endif;?></td><td><strong><?= em_money($o['total_cents']) ?></strong></td><td><?= $o['channel']==='delivery'?Security::e($o['delivery_name']??'—'):'—' ?><?php if($o['channel']==='delivery'&&Auth::can('delivery.assign')):?><form method="post" class="actions" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="assign-delivery"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="delivery_user_id"><option value="0">Sem entregador</option><?php foreach($deliveries as$du):?><option value="<?= (int)$du['id'] ?>"<?= em_selected($o['assigned_delivery_user_id']??0,$du['id']) ?>><?= Security::e($du['name']) ?></option><?php endforeach;?></select><button class="secondary">Atribuir</button></form><?php endif;?></td><td><div class="actions"><a class="button secondary" href="<?= Security::e(app_url('?route=orders&view='.(int)$o['id'])) ?>">Detalhes</a><?php if(Auth::can('orders.fulfill')&&in_array($o['channel'],['counter','pickup'],true)&&!empty($o['public_token'])):?><a class="button secondary" href="<?= Security::e(app_url('?route=pickup&token='.rawurlencode((string)$o['public_token']))) ?>">Retirada</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section><?php em_footer();
